## 2. Reactive MongoDB + Kotlin Coroutine

### 2.1 ReactiveMongoTemplate과 Coroutine 변환

Spring Data MongoDB의 Reactive 모듈은 `Flux`/`Mono`를 반환하지만, Kotlin에서는 `Flow`/`suspend` 함수로 자연스럽게 변환할 수 있다.

```kotlin
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.reactive.asFlow
import kotlinx.coroutines.reactive.awaitSingle
import kotlinx.coroutines.reactive.awaitSingleOrNull

@Service
class OrderService(
    private val reactiveMongoTemplate: ReactiveMongoTemplate
) {
    // Mono -> suspend function
    suspend fun findById(orderId: String): Order? {
        return reactiveMongoTemplate.findById(orderId, Order::class.java)
            .awaitSingleOrNull()
    }

    // Mono -> suspend function
    suspend fun save(order: Order): Order {
        return reactiveMongoTemplate.save(order)
            .awaitSingle()
    }

    // Flux -> Flow
    fun findByStatus(status: String): Flow<Order> {
        return reactiveMongoTemplate.find(
            Query.query(Criteria.where("status").`is`(status)),
            Order::class.java
        ).asFlow()
    }

    // Aggregation + Flow
    fun getOrderSummaryByUser(): Flow<UserOrderSummary> {
        val aggregation = Aggregation.newAggregation(
            Aggregation.group("userId")
                .count().`as`("orderCount")
                .sum("totalAmount").`as`("totalSpent"),
            Aggregation.sort(Sort.Direction.DESC, "totalSpent")
        )
        return reactiveMongoTemplate.aggregate(
            aggregation, "orders", UserOrderSummary::class.java
        ).asFlow()
    }
}
```

### 2.2 Coroutine Repository

```kotlin
interface OrderCoroutineRepository : CoroutineMongoRepository<Order, String> {
    suspend fun findByUserId(userId: String): List<Order>
    fun findByStatusOrderByCreatedAtDesc(status: String): Flow<Order>
    suspend fun countByStatus(status: String): Long
}
```

