## 3. Custom Converter

### 3.1 Value Object 변환

```kotlin
// Value Object 정의
@JvmInline
value class Money(val amount: BigDecimal) {
    init {
        require(amount >= BigDecimal.ZERO) { "금액은 0 이상이어야 합니다" }
    }
}

@JvmInline
value class Email(val value: String) {
    init {
        require(value.matches(Regex("^[\\w.-]+@[\\w.-]+\\.[a-zA-Z]{2,}$"))) {
            "유효하지 않은 이메일 형식입니다"
        }
    }
}

// ReadingConverter: MongoDB -> Kotlin
@ReadingConverter
class MoneyReadConverter : Converter<Decimal128, Money> {
    override fun convert(source: Decimal128): Money {
        return Money(source.bigDecimalValue())
    }
}

// WritingConverter: Kotlin -> MongoDB
@WritingConverter
class MoneyWriteConverter : Converter<Money, Decimal128> {
    override fun convert(source: Money): Decimal128 {
        return Decimal128(source.amount)
    }
}
```

### 3.2 암호화 필드 Converter

```kotlin
@WritingConverter
class EncryptedStringWriteConverter(
    private val encryptionService: EncryptionService
) : Converter<SensitiveString, String> {
    override fun convert(source: SensitiveString): String {
        return encryptionService.encrypt(source.value)
    }
}

@ReadingConverter
class EncryptedStringReadConverter(
    private val encryptionService: EncryptionService
) : Converter<String, SensitiveString> {
    override fun convert(source: String): SensitiveString {
        return SensitiveString(encryptionService.decrypt(source))
    }
}

// Converter 등록
@Configuration
class MongoConverterConfig(
    private val encryptionService: EncryptionService
) {
    @Bean
    fun customConversions(): MongoCustomConversions {
        return MongoCustomConversions(listOf(
            MoneyReadConverter(),
            MoneyWriteConverter(),
            EncryptedStringWriteConverter(encryptionService),
            EncryptedStringReadConverter(encryptionService)
        ))
    }
}
```

